// 动态计算 basename，适配多种部署环境：
// 1. 妙搭平台：读 window.__BASENAME__（服务端注入），只在 /app/ 路径下生效
// 2. 根路径部署（本地开发、自有域名） → '/'
// 3. GitHub Pages 子路径 /repo-name/  → '/repo-name'
//
// 探测优先级（从高到低）：
// 1. 妙搭平台 window.__BASENAME__（服务端注入，最准确）
// 2. 从页面 script[src] 探测 assets 目录位置 → 反推站点根（最可靠，不依赖 URL pathname）
// 3. 从 URL pathname 推断（兜底方案，依赖 KNOWN_ROUTES 列表）
//
// 关键修复：script 标签探测方案不依赖已知路由列表，
// 直接基于实际部署的资源位置反推 base path，彻底解决 GitHub Pages 子路径图片 404 问题

import { resolveAppUrl, getAppId } from '@lark-apaas/client-toolkit-lite';

// 声明全局变量类型（妙搭平台服务端注入）
declare global {
  interface Window {
    __BASENAME__?: string;
    appId?: string;
  }
}

const KNOWN_ROUTES = [
  'products',
  'about',
  'contact',
  'news',
  'admin',
  'privacy-policy',
  'faqs',
];

// 缓存探测结果，避免重复计算
let cachedBasename: string | null = null;

/**
 * 判断当前是否运行在妙搭平台环境
 * 检测依据：URL pathname 以 /app/ 开头
 */
export function isMiaodaPlatform(): boolean {
  if (typeof window === 'undefined') return false;
  const pathname = window.location.pathname;
  // 妙搭平台路径格式：/app/<app_id>/...
  return pathname.startsWith('/app/');
}

/**
 * 从页面 script 标签的 src 属性探测站点根路径
 *
 * 原理：vite 构建的产物中，index.html 引用的 JS 文件路径形式为
 * ./assets/index-xxxx.js 或 /repo-name/assets/index-xxxx.js
 * 通过找到包含 /assets/index- 的 script src，反推出站点根路径（assets/ 目录的父目录）
 *
 * 这个方案最可靠，因为它直接基于实际部署的资源位置，
 * 不依赖 URL pathname 推断，也不依赖已知路由列表。
 *
 * @returns basename 路径（如 '/led-sensor-light' 或 '/'），探测失败返回 null
 */
function detectBasenameFromScripts(): string | null {
  if (typeof document === 'undefined' || typeof window === 'undefined') return null;

  const scripts = document.querySelectorAll<HTMLScriptElement>('script[src]');
  for (const script of Array.from(scripts)) {
    const src = script.src; // 绝对 URL（浏览器已解析）
    if (!src) continue;

    // 找包含 /assets/index- 的 script（vite 构建的主入口）
    const assetsIndex = src.indexOf('/assets/index-');
    if (assetsIndex === -1) continue;

    try {
      const url = new URL(src, window.location.href);
      const pathname = url.pathname; // 如 /led-sensor-light/assets/index-xxx.js
      const assetsIdx = pathname.indexOf('/assets/index-');
      if (assetsIdx === -1) continue;

      const basePath = pathname.slice(0, assetsIdx); // 如 /led-sensor-light
      if (basePath === '') return '/'; // assets 在根目录
      return basePath;
    } catch {
      // URL 解析失败，跳过
    }
  }

  // 没找到 assets/index-，试试找 polyfills.js 或其他 vite 产物
  for (const script of Array.from(scripts)) {
    const src = script.src;
    if (!src) continue;

    const assetsIndex = src.indexOf('/assets/');
    if (assetsIndex === -1) continue;

    try {
      const url = new URL(src, window.location.href);
      const pathname = url.pathname;
      const assetsIdx = pathname.indexOf('/assets/');
      if (assetsIdx === -1) continue;

      const basePath = pathname.slice(0, assetsIdx);
      if (basePath === '') return '/';
      return basePath;
    } catch {
      // 跳过
    }
  }

  return null;
}

/**
 * 从 URL pathname 推断 basename（兜底方案）
 * 已知路由名的第一段不算 basename，其他情况视为子路径部署
 *
 * 支持的路径模式：
 * - /                      → '/'       (根路径部署)
 * - /products              → '/'       (根路径部署，已知路由)
 * - /repo-name/            → '/repo-name'  (GitHub Pages 子路径)
 * - /repo-name/products    → '/repo-name'  (GitHub Pages 子路径)
 * - /app/app_id/           → '/app/app_id' (妙搭平台)
 */
function inferBasenameFromPathname(): string {
  if (typeof window === 'undefined') return '/';

  const pathname = window.location.pathname;
  const parts = pathname.split('/').filter(Boolean);

  // 空路径 = 根路径
  if (parts.length === 0) return '/';

  // 妙搭平台特殊路径：/app/<app_id>/...
  if (parts[0] === 'app' && parts.length >= 2 && !KNOWN_ROUTES.includes(parts[1])) {
    return '/' + parts[0] + '/' + parts[1];
  }

  // 第一段是已知路由名，部署在根路径
  if (KNOWN_ROUTES.includes(parts[0])) {
    return '/';
  }

  // 其他情况：第一段是仓库名（GitHub Pages 等子路径部署）
  return '/' + parts[0];
}

/**
 * 获取应用 basename
 *
 * 探测优先级（从高到低）：
 * 1. 妙搭平台 window.__BASENAME__（服务端注入，最准确）
 * 2. 从 script 标签 src 探测（最可靠，基于实际资源位置）
 * 3. 从 URL pathname 推断（兜底方案）
 */
export function getDynamicBasename(): string {
  // 非浏览器环境返回 /
  if (typeof window === 'undefined') return '/';

  // 返回缓存结果
  if (cachedBasename !== null) return cachedBasename;

  const onMiaoda = isMiaodaPlatform();

  if (onMiaoda) {
    // 妙搭平台环境：优先读服务端注入的 __BASENAME__
    if (window.__BASENAME__ && window.__BASENAME__ !== '/') {
      cachedBasename = window.__BASENAME__.endsWith('/')
        ? window.__BASENAME__.slice(0, -1)
        : window.__BASENAME__;
      return cachedBasename;
    }

    // 兜底读构建时注入的 CLIENT_BASE_PATH（妙搭平台 build 时由 preset 设置）
    const envBasename = (process as unknown as { env: Record<string, string | undefined> }).env
      .CLIENT_BASE_PATH;
    if (envBasename && envBasename !== '' && envBasename !== '/') {
      cachedBasename = envBasename.endsWith('/') ? envBasename.slice(0, -1) : envBasename;
      return cachedBasename;
    }

    // 再兜底：从 URL 推断
    cachedBasename = inferBasenameFromPathname();
    return cachedBasename;
  }

  // 非妙搭平台环境（GitHub Pages / 自有域名 / 本地开发）
  // 方案 A：从 script 标签 src 探测（最可靠）
  const detected = detectBasenameFromScripts();
  if (detected) {
    cachedBasename = detected;
    return cachedBasename;
  }

  // 方案 B：兜底从 URL pathname 推断
  cachedBasename = inferBasenameFromPathname();
  return cachedBasename;
}

/**
 * 清除 basename 缓存（测试用）
 */
export function _resetBasenameCache(): void {
  cachedBasename = null;
}

/**
 * 拼接应用资源路径
 * 在妙搭平台等子路径部署环境下，自动加上 basename 前缀
 */
export function withBasename(path: string): string {
  const base = getDynamicBasename();
  if (base === '/' || base === '') return path;
  // 平台内部路径（spark / aily 服务等）本身已包含完整上下文，不能再拼 basename
  if (
    path.startsWith('/spark/') ||
    path.startsWith('/aily/') ||
    path.startsWith('/runtime/') ||
    path.startsWith(base + '/') ||
    path === base
  ) {
    return path;
  }
  if (path.startsWith('/')) return base + path;
  return base + '/' + path;
}

/**
 * 兼容 resolveAppUrl：
 * - 妙搭平台环境下使用 SDK 的 resolveAppUrl
 * - GitHub Pages 等环境下使用本地 basename 拼接
 */
export function resolveAssetUrl(path: string): string {
  // 平台内部服务路径（spark / aily / runtime 等）本身已包含完整上下文，
  // 不能再走 resolveAppUrl / withBasename 拼 basename，否则会造成双层 app_id 嵌套
  if (
    typeof path === 'string' &&
    (path.startsWith('/spark/') ||
      path.startsWith('/aily/') ||
      path.startsWith('/runtime/') ||
      path.startsWith('data:') ||
      path.startsWith('blob:') ||
      /^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(path))
  ) {
    return path;
  }
  if (isMiaodaPlatform()) {
    try {
      return resolveAppUrl(path);
    } catch {
      return withBasename(path);
    }
  }
  // GitHub Pages / 自有域名环境：直接用本地 basename 拼接
  // 避免 SDK 的 resolveAppUrl 返回妙搭平台格式的路径
  return withBasename(path);
}

/**
 * 获取当前 appId（兼容多环境）
 */
export function getCurrentAppId(): string {
  if (typeof window !== 'undefined' && window.appId) {
    return window.appId;
  }
  try {
    return getAppId() ?? 'app';
  } catch {
    return 'app';
  }
}
